pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address ownerCandidate) public {
        // ownerCandidate is an arbitrary address; the reference must return the actual owner,
        // which is address(this) at deployment, never address(0).
        // The bug returns address(0) no matter what, so it breaks the invariant.
        address currentOwner = c.owner();
        assertTrue(currentOwner != address(0));
    }
}

