pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        vm.prank(address(this));
        try c.transferOwnership(newOwner) {
            assertEq(c.owner(), newOwner);
        } catch {
            // reference reverts for newOwner == address(0), buggy doesn't
            assertTrue(false, "transferOwnership should succeed for non-zero address");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // First renounce ownership so that owner becomes address(0) (this is allowed in both versions)
        c.renounceOwnership();
        // Now attempt to transfer ownership to a non-zero address
        c.transferOwnership(newOwner);
        // In the reference version, the require(newOwner != address(0)) would have prevented the transfer from address(0) to newOwner? 
        // Actually, the reference version would revert because newOwner is checked against address(0) inside transferOwnership, and that check passes.
        // The critical difference: The mutant removed the require that newOwner != address(0). That means in the mutant, if owner is currently address(0), 
        // calling transferOwnership(nonZero) will set owner to nonZero. In the reference, it would also set owner to nonZero because newOwner != address(0) passes the check. 
        // Wait, the bug is exactly about allowing transfer to address(0). So if newOwner == address(0), the reference reverts, the mutant doesn't.
        // We need a scenario where the rule fails for the mutant but passes for reference for some input. The simple rule: after calling transferOwnership(newOwner),
        // if newOwner == address(0), the call should revert. In the reference it does, in the mutant it doesn't. But the fuzzer will search for address(0) input.
        // However, the previous attempt "For any newOwner != address(0), transferOwnership(newOwner) must set owner() to newOwner" passes for both because both set it.
        // To truly distinguish, we need to use the fact that the mutant allows owner to become address(0), and once it is address(0), a subsequent transferOwnership(nonZero) 
        // will set it to nonZero (still allowed) - that doesn't break it. But what if we call transferOwnership(address(0)) directly? The reference reverts, mutant doesn't.
        // So the rule: "Calling transferOwnership(address(0)) must revert." That's a simple assertion.
        // But the instruction says: "Take the deciding values as FUZZ PARAMETERS of the test function." So we can fuzz newOwner, and assume(newOwner != address(0)) 
        // would exclude the bug-triggering input. So we should NOT exclude address(0). Let the fuzzer find address(0). Then we wrap in try/catch.
        // The rule: for any input, transferOwnership should succeed if and only if newOwner != address(0). The mutant succeeds even for address(0).
        // So we can assert: (newOwner == address(0)) == !success.
        bool success;
        try c.transferOwnership(newOwner) { success = true; } catch { success = false; }
        assertTrue((newOwner != address(0)) == success);
    }
}

